/**
 * Numerical parity: `runFactorAnova` must reproduce omicViz's ACTUAL two-way
 * implementation. Fixtures are generated by running omicViz's
 * _run_two_way_anova + _finalise on synthetic standardized data (same raw input
 * fed to both), covering the symmetric (cell×time) and asymmetric
 * (cmpd×cell, vehicle dose-excluded) code paths. stat_type = pP. The former Welch test is kept as
 * `variance: 'welch'` for this; the model's default reads the same 2×2s (checked here too).
 */
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

import Papa from 'papaparse'
import { describe, expect, it } from 'vitest'

import { runFactorAnova, type AnovaFactorPick } from './twoWay'
import { DEFAULT_THRESHOLD } from './stats'
import {
  termless,
  type CompareResultRow,
  type ConditionKey,
  type Pair,
  type StandardRow
} from './types'

const here = dirname(fileURLToPath(import.meta.url))
const fx = (name: string): string => readFileSync(join(here, '__fixtures__', name), 'utf8')

type Rec = Record<string, string>

function toRows(csv: string): StandardRow[] {
  const recs = Papa.parse<Rec>(csv, { header: true, skipEmptyLines: true }).data.filter(
    (r) => r.uniqID
  )
  return recs.map((r) => ({
    uniqID: r.uniqID,
    cell: r.cell ?? '',
    cmpd: r.cmpd ?? '',
    dose: r.dose !== undefined ? Number(r.dose) : null,
    time: r.time !== undefined ? Number(r.time) : null,
    rep: Number(r.rep),
    value: Number(r.value)
  }))
}

interface ExpectedRow {
  uniqID: string
  log2FC: string
  pP: string
  pQ: string
  signf: string
}

function checkParity(
  inputFile: string,
  expectedFile: string,
  factors: [AnovaFactorPick, AnovaFactorPick],
  active: ConditionKey[]
): void {
  // omicViz's own test: each 2×2 by Welch on its four cells
  const res = runFactorAnova({
    rows: toRows(fx(inputFile)),
    factors,
    activeConditions: active,
    threshold: { ...DEFAULT_THRESHOLD, statType: 'pP' },
    variance: 'welch'
  })
  // The model (default) reads the same 2×2s: the same rows, comparisons, contexts and log₂FC —
  // only the test's variance differs.
  const model = runFactorAnova({
    rows: toRows(fx(inputFile)),
    factors,
    activeConditions: active,
    threshold: { ...DEFAULT_THRESHOLD, statType: 'pP' }
  })
  // (the model's term rows come on top — compared here: the 2×2s)
  expect(model.comparisons.slice(0, res.comparisons.length)).toEqual(res.comparisons)
  expect(termless(model.rows).length).toBe(res.rows.length)
  const keyOf = (r: CompareResultRow): string =>
    [r.uniqID, r.comparison, r.cmp_cond, r.cell, r.cmpd, r.dose, r.time].join('|')
  const byKey = new Map(termless(model.rows).map((r) => [keyOf(r), r]))
  for (const r of res.rows) {
    const m = byKey.get(keyOf(r))
    expect(m, `model row for ${keyOf(r)}`).toBeDefined()
    expect(m!.log2FC as number).toBeCloseTo(r.log2FC as number, 9)
  }
  const expected = Papa.parse<ExpectedRow>(fx(expectedFile), {
    header: true,
    skipEmptyLines: true
  }).data.filter((r) => r.uniqID)

  const actual = new Map<string, CompareResultRow>(res.rows.map((r) => [r.uniqID, r]))

  expect(
    expected.every((e) => actual.has(e.uniqID)),
    'all expected genes present'
  ).toBe(true)
  expect(res.rows.length).toBe(expected.length)

  for (const e of expected) {
    const a = actual.get(e.uniqID)!
    const near = (got: number | null, want: string, field: string): void => {
      if (want.trim() === '') return
      const w = Number(want)
      if (!Number.isFinite(w)) return
      expect(got, `${field} @ ${e.uniqID}`).not.toBeNull()
      expect(Math.abs((got as number) - w), `${field} @ ${e.uniqID}`).toBeLessThan(1e-6)
    }
    near(a.log2FC, e.log2FC, 'log2FC')
    near(a.pP, e.pP, 'pP')
    near(a.pQ, e.pQ, 'pQ')
    expect(a.signf, `signf @ ${e.uniqID}`).toBe(e.signf.toLowerCase() === 'true')
  }
}

const p = (n: string, d: string): Pair => [n, d]

describe('two_way_anova parity vs omicViz', () => {
  it('symmetric cell × time', () => {
    checkParity(
      'twoway_sym_input.csv',
      'expected_twoway_sym.csv',
      [
        { condition: 'cell', pairs: [p('M', 'W')] },
        { condition: 'time', pairs: [p('1', '2')] }
      ],
      ['cell', 'time']
    )
  })

  it('asymmetric cmpd × cell (vehicle dose-excluded)', () => {
    checkParity(
      'twoway_asym_input.csv',
      'expected_twoway_asym.csv',
      [
        { condition: 'cmpd', pairs: [p('E28', 'DMSO')] },
        { condition: 'cell', pairs: [p('M', 'W')] }
      ],
      ['cmpd', 'cell', 'dose']
    )
  })
})
